import{_ as t,H as a,f as r,i as n}from"./chunks/framework.BH2BK_3i.js";const b=JSON.parse('{"title":"用户来信 | 真好，面试考到这些并发编程，我都答对了！","description":"","frontmatter":{},"headers":[{"level":2,"title":"我是如何通过专栏拿到 Offer 的？","slug":"我是如何通过专栏拿到-offer-的","link":"#我是如何通过专栏拿到-offer-的","children":[]},{"level":2,"title":"我是如何进行高效学习的呢？","slug":"我是如何进行高效学习的呢","link":"#我是如何进行高效学习的呢","children":[{"level":3,"title":"第一，直接上手跟着敲一遍代码。","slug":"第一-直接上手跟着敲一遍代码。","link":"#第一-直接上手跟着敲一遍代码。","children":[]},{"level":3,"title":"第二，换位理解。","slug":"第二-换位理解。","link":"#第二-换位理解。","children":[]},{"level":3,"title":"第三，坚持，坚持，再坚持。","slug":"第三-坚持-坚持-再坚持。","link":"#第三-坚持-坚持-再坚持。","children":[]}]},{"level":2,"title":"再说专栏的 2 个宝藏之地","slug":"再说专栏的-2-个宝藏之地","link":"#再说专栏的-2-个宝藏之地","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"宝令老师的回信：","slug":"宝令老师的回信","link":"#宝令老师的回信","children":[]}],"relativePath":"Java并发编程实战/用户来信-真好，面试考到这些并发编程，我都答对了！.md","filePath":"Java并发编程实战/用户来信-真好，面试考到这些并发编程，我都答对了！.md","lastUpdated":1779815850000}'),o={name:"Java并发编程实战/用户来信-真好，面试考到这些并发编程，我都答对了！.md"};function l(i,e,s,p,g,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="用户来信-真好-面试考到这些并发编程-我都答对了" tabindex="-1">用户来信 | 真好，面试考到这些并发编程，我都答对了！ <a class="header-anchor" href="#用户来信-真好-面试考到这些并发编程-我都答对了" aria-label="Permalink to &quot;用户来信 | 真好，面试考到这些并发编程，我都答对了！&quot;">​</a></h1><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/102300/228d35b6802062d21d3391c6b54ad757.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/102300/228d35b6802062d21d3391c6b54ad757.jpg" alt="unpreview"></a></p><p>你好，我是Zed，是《Java并发编程实战》1W+订阅者中的一员。</p><p>我从事Java开发已有五年时间了，曾在一家国内知名物流企业工作，现在杭州一家金融支付类公司继续担任Java工程师一职。</p><p>大概在今年四月份，在高铁上翻到一篇文章，讲的是“为什么Object.wait()方法一定要在synchronized内部使用”，因为之前我根本不知道这个问题，所以打算考考我朋友。</p><p>结果他给了我一些迥然不同的答案，并邀请我读了宝令老师的《Java并发编程实战》专栏中的一篇文章 <a href="https://time.geekbang.org/column/article/86089" target="_blank" rel="noreferrer">《08 | 管程：并发编程的万能钥匙》</a>，看完后我感觉醍醐灌顶，津津有味，果断开始学习。</p><h2 id="我是如何通过专栏拿到-offer-的" tabindex="-1">我是如何通过专栏拿到 Offer 的？ <a class="header-anchor" href="#我是如何通过专栏拿到-offer-的" aria-label="Permalink to &quot;我是如何通过专栏拿到 Offer 的？&quot;">​</a></h2><p>机缘巧合，专栏学习到一半时 ，我辞掉了原有的工作出去面试。因为面试的岗位都是高级工程师，所以基本上离不开并发编程的问题， <strong>像锁、线程安全、线程池、并发工具类都是家常便饭</strong>。</p><p>印象比较深刻的是面试官问我： <strong>线程池的大小如何确定</strong>？</p><p>那时我刚看完 <a href="https://time.geekbang.org/column/article/86666" target="_blank" rel="noreferrer">《10 | Java线程（中）：创建多少线程才是合适的？》</a>，然后就胸有成竹且不紧不慢地回答了，面试官听了直点头。</p><p>另外一个问题是： <strong>怎么理解活锁</strong>？</p><p>于是，我又如法炮制搬出了 <a href="https://time.geekbang.org/column/article/85702" target="_blank" rel="noreferrer">《07 | 安全性、活跃性以及性能问题》</a> 中老师提到“路人甲乙相撞”的例子，同时给出具体的解决方案。</p><p>不得不说，这个例子太经典了，这里我必须再展示给大家看！在文章里老师是这样描述 <strong>活锁</strong> 的：</p><blockquote><p>所谓的“活锁”，可以类比现实世界里的例子。路人甲从左手边出门，路人乙从右手边进门，两人为了不相撞，互相谦让，路人甲让路走右手边，路人乙也让路走左手边，结果是两人又相撞了。</p><p>这种情况，基本上谦让几次就解决了，因为人会交流啊。可是如果这种情况发生在编程世界了，就有可能会一直没完没了地“谦让”下去，成为没有发生阻塞但依然执行不下去的“活锁”。</p></blockquote><p>并且给出了简单有效的 <strong>解决方案</strong>：</p><blockquote><p>解决“活锁”的方案很简单：谦让时，尝试等待一个随机的时间就可以了。</p><p>例如上面的那个例子，路人甲走左手边发现前面有人，并不是立刻换到右手边，而是等待一个随机的时间后，再换到右手边；同样，路人乙也不是立刻切换路线，也是等待一个随机的时间再切换。由于路人甲和路人乙等待的时间是随机的，所以同时相撞后再次相撞的概率就很低了。</p><p>“等待一个随机时间”的方案虽然很简单，却非常有效，Raft这样知名的分布式一致性算法中也用到了它。</p></blockquote><p>真的很庆幸提前遇到了并发专栏，我的面试顺利通过了。</p><p>我可以很负责任地说，如果没有专栏的学习，我不会那么顺利地找到工作。换句话说， <strong>专栏其实涵盖了几乎所有大家面试可能会被问到的内容</strong>。</p><h2 id="我是如何进行高效学习的呢" tabindex="-1">我是如何进行高效学习的呢？ <a class="header-anchor" href="#我是如何进行高效学习的呢" aria-label="Permalink to &quot;我是如何进行高效学习的呢？&quot;">​</a></h2><h3 id="第一-直接上手跟着敲一遍代码。" tabindex="-1">第一，直接上手跟着敲一遍代码。 <a class="header-anchor" href="#第一-直接上手跟着敲一遍代码。" aria-label="Permalink to &quot;第一，直接上手跟着敲一遍代码。&quot;">​</a></h3><p>我觉得最能表示你在用心学习的方式就是 <strong>付诸实际行动</strong> 了，就拿专栏第一模块“并发理论基础”来讲，会涉及到很多的例子，比如：</p><ul><li>可见性、原子性等问题的举例说明，直接看 <a href="https://time.geekbang.org/column/article/83682" target="_blank" rel="noreferrer">《01 | 可见性、原子性和有序性问题：并发编程Bug的源头》</a>；</li><li>用“银行转账模拟”的例子引出死锁问题并如何处理， <a href="https://time.geekbang.org/column/article/85001" target="_blank" rel="noreferrer">《05 | 一不小心就死锁了，怎么办？》</a>；</li><li>如何保证线程安全的同时保证性能， <a href="https://time.geekbang.org/column/article/85241" target="_blank" rel="noreferrer">《06 | 用“等待-通知”机制优化循环等待》</a>。</li><li>……</li></ul><p>针对这些例子，我能做的就是自己花时间，手动敲一遍代码。要知道，纸上得来终觉浅，绝知此事要躬行！</p><h3 id="第二-换位理解。" tabindex="-1">第二，换位理解。 <a class="header-anchor" href="#第二-换位理解。" aria-label="Permalink to &quot;第二，换位理解。&quot;">​</a></h3><p>这也是我觉得最为有效的学习方式之一， <strong>站在老师角度，去思考他是如何看这个问题的，他是如何一步步讲解清楚的</strong>。而且，宝令老师在每篇文章后面，都会有一段总结，非常有效地来帮助我去获得这篇文章的知识点。 <strong>提出问题—解决问题—总结得出结论，这关键的三步，在任何地方都适用</strong>。</p><p>所以，我还会花时间思考专栏的“这里”或“那里”跟我之前的理解是否有出入，例如 <a href="https://time.geekbang.org/column/article/86695" target="_blank" rel="noreferrer">《11 | Java线程（下）：为什么局部变量是线程安全的？》</a> 中对局部变量线程安全的解释，跟自己了解的虚拟机执行过程变量共享关系是否吻合？</p><p><strong>反复问自己问题的答案是什么，然后和老师的理解做对比</strong>，收获感和进步才会是巨大的。</p><h3 id="第三-坚持-坚持-再坚持。" tabindex="-1">第三，坚持，坚持，再坚持。 <a class="header-anchor" href="#第三-坚持-坚持-再坚持。" aria-label="Permalink to &quot;第三，坚持，坚持，再坚持。&quot;">​</a></h3><p>学习最难的也是最有价值的一点就是“ <strong>坚持</strong>”，所以每天我都会主动去看专栏，包括相关书籍以及网上的各类资料。学习到新的知识是一件多么幸福的事情，每天一点点，这日积月累下来就是一笔不小的财富。我们办公室就有一个有趣的墙画，内容就是：</p><p>1.01365=37.8；</p><p>而1.02365=1 377.4。</p><p>每天跟着专栏去渗透，每一句话都读得很细致，每次看到后一句忘记前面说的都会返回去再读一遍直到弄懂为止。 <strong>知识一定要彻底掌握才能被更好地使用</strong>，这是我个人的要求。需要补充一句， <strong>学习的时候切记要结合源码去看，事半功倍</strong>！</p><h2 id="再说专栏的-2-个宝藏之地" tabindex="-1">再说专栏的 2 个宝藏之地 <a class="header-anchor" href="#再说专栏的-2-个宝藏之地" aria-label="Permalink to &quot;再说专栏的 2 个宝藏之地&quot;">​</a></h2><p>除此之外，还有两个我很喜欢的、也很激励我学习的点。</p><p><strong>第一个，每一篇文章最后都会有思考题，而思考题的背后就是众多同学的头脑风暴。</strong></p><p>每篇文章的留言我都会细细去看，看同学们的回答以及提问我是否了解，如果了解，就暗暗地“得意”一番；如果没有，那就说明我还没完全弄明白，路漫漫仍需继续努力。</p><p>所以， <strong>留言区也是一个宝藏之地</strong>，有些同学的回答甚至可能比老师举的例子更加让人印象深刻，例如 <a href="https://time.geekbang.org/column/article/83682" target="_blank" rel="noreferrer">《01 | 可见性、原子性和有序性问题：并发编程Bug的源头》</a> 下的留言，两个字，精彩！当初读完第一章的时候我就暗下决心，绝不能输给这些同学。</p><p>这也侧面反映了一点： <strong>自己拿一本书去看去学，和你潜意识里知道有很多人在跟你一起学，效果是完全不一样的</strong>。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/102300/d5e1a7d0a501e8e19b78ef81d3a11413.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/102300/d5e1a7d0a501e8e19b78ef81d3a11413.jpg" alt=""></a></p><p><strong>第二个，热点问题答疑，这也是宝令老师专栏的特色了。</strong></p><p>每一模块的最后都会专门有一篇文章去详细回答各类问题，看这类问题的同时我自己脑子里存储的各类知识也都会融会贯通起来，不知不觉中 <strong>勾勒出自己的知识全景图</strong>，很有成就感。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>平心而论， <strong>如果不是因为这个专栏，我想我不会学得这么快、学得这么好、中间找工作也找得那么顺利</strong>。当初也是被宝令老师的知识总结以及传授方式所吸引，才选择去订阅，看完专栏第一个模块就的确感觉学了很多很多，收获颇丰。</p><p>所以，我可以拍胸脯说：这是我订阅的所有专栏里最值的一个！</p><p>在结束语中，宝令老师说他自己好为人师，作为读者的我确实感受到了。专栏下面的留言，老师都会耐心去解答，看回复也能收获很多。后续也希望老师能继续输出一些自己的所得和见解，而我们，则 <strong>站在巨人的肩膀上，遇见我们最美好的风景</strong>！</p><p>在最后，我也附上我自己学习过程中的 <a href="https://github.com/Fadezed/concurrency" target="_blank" rel="noreferrer">一些代码积累</a>。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/102300/3bff102888cec5c7bfbc35a1fdeda0db.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/102300/3bff102888cec5c7bfbc35a1fdeda0db.jpg" alt=""></a></p><h2 id="宝令老师的回信" tabindex="-1">宝令老师的回信： <a class="header-anchor" href="#宝令老师的回信" aria-label="Permalink to &quot;宝令老师的回信：&quot;">​</a></h2><p>首先，恭喜 Zed 顺利收获一份新工作。我觉得能通过面试只有一个原因就是 <strong>技术水平过关，并发相关的知识和技术到位，面试自然就轻松了。</strong></p><p><strong>感谢你分享的学习方法，尤其是第一点：直接上手跟着敲一遍代码。</strong> 我们搞工程的必须上手才能理解的更深刻，所以专栏一直都没有给出一份完整的代码，更希望大家自己去动手。</p><p><strong>大致浏览了一下你在 Github 分享的代码以及知识点的总结，代码写的很规范，能看出来很用心</strong>，我觉得你的新东家眼光很不错！</p><p>非常感谢 Zed 及大家，能坚持看完我的专栏，并能运用在实际工作中，真的值了。 <strong>也欢迎大家把这篇文章分享给朋友，相互学习，互相激励</strong>。</p>',52)])])}const d=t(o,[["render",l]]);export{b as __pageData,d as default};
